from pathlib import Path
from html import escape
p=Path('outputs/phase-ii-founder-gate')
items=[('form-symbol-1440','FORM / Symbol'),('form-language-1440','FORM / Language'),('form-spatial-1440','FORM / Spatial'),('form-interface-1440','FORM / Interface'),('form-environment-1440','FORM / Environment'),('form-primary-390','FORM / Mobile'),('package-dieline-1440','SURFACE / STRUCTURE / Dieline'),('package-fold-25-1440','25% / Primary folds'),('package-volume-50-1440','50% / Volume'),('package-closure-75-1440','75% / Closure'),('package-finished-closed-1440','Finished / Closed'),('package-finished-open-1440','Finished / Open'),('package-finished-390','Finished / Mobile')]
html='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><meta name="robots" content="noindex,nofollow"><title>DWS — Phase II Founder Gate</title><style>body{margin:0;background:#eeeae3;color:#222;font:16px Arial,sans-serif}header,section{padding:40px 5%}h1{font-size:clamp(32px,5vw,70px);max-width:900px;letter-spacing:-.04em}p{max-width:800px;line-height:1.7}nav{display:flex;gap:20px;flex-wrap:wrap}a{color:inherit}figure{margin:30px 0 70px}img{display:block;max-width:100%;height:auto;border:1px solid #ccc}figure.mobile img{max-width:390px}figcaption{margin:15px 0}h2{font-size:32px}small{font-size:12px}</style><header><small>DWS / PHASE II / FOUNDER GATE</small><h1>One identity. Seven behaviors.<br>One sheet. A structural reveal.</h1><p>New captures from this refinement only. Signal and Assets 01–03 are locked and unchanged. Nothing deployed. Packaging is a native structural concept, not a manufacturing-validated dieline.</p><nav><a href="http://127.0.0.1:5194/capability-lab/identity">Open FORM</a><a href="http://127.0.0.1:5194/capability-lab/packaging">Open SURFACE / STRUCTURE</a><a href="#form">FORM captures</a><a href="#package">Package captures</a></nav></header><section id="form"><h2>05 / FORM</h2>'''
for i,(name,label) in enumerate(items):
 if i==6:html+='</section><section id="package"><h2>06 / SURFACE / STRUCTURE</h2>'
 html+=f'<figure class="{"mobile" if "390" in name else "desktop"}"><figcaption>{escape(label)} — {"390 × 844" if "390" in name else "1440 × 1000"}</figcaption><a href="{name}.png"><img src="{name}.png" alt="{escape(label)}" loading="lazy"></a></figure>'
html+='</section></html>'
(p/'index.html').write_text(html)
